html:
{%- set c = label_context(doc) -%}
{%- set page_w = c.width * c.per_row + c.gap * (c.per_row - 1) -%}
<meta name="pdfkit-page-width" content="{{ page_w }}mm">
<meta name="pdfkit-page-height" content="{{ c.height }}mm">
<meta name="pdfkit-margin-top" content="0mm">
<meta name="pdfkit-margin-bottom" content="0mm">
<meta name="pdfkit-margin-left" content="0mm">
<meta name="pdfkit-margin-right" content="0mm">
<style>
	@page { size: {{ page_w }}mm {{ c.height }}mm; margin: 0; }
	html, body { margin: 0 !important; padding: 0 !important; background: #fff; }
	.print-format { padding: 0 !important; margin: 0 !important; max-width: none !important; width: {{ page_w }}mm !important; min-height: 0 !important; }
	.rbl-row { width: {{ page_w }}mm; height: {{ c.height }}mm; border-collapse: collapse; table-layout: fixed;
		page-break-after: always; break-after: page; page-break-inside: avoid; }
	.rbl-row:last-child { page-break-after: auto; break-after: auto; }
	.rbl-row td { padding: 0 !important; vertical-align: top; border: 0 !important; }
	.rbl-gap { width: {{ c.gap }}mm; }
	.rbl { width: {{ c.width }}mm; height: {{ c.height }}mm; overflow: hidden; box-sizing: border-box;
		padding: {{ c.height * 0.04 }}mm {{ c.width * 0.04 }}mm; font-family: Arial, Helvetica, sans-serif; color: #000; line-height: 1.1; }
	.rbl-name { font-weight: 700; font-size: {{ c.height * 0.12 }}mm; height: {{ c.height * 0.15 }}mm; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
	.rbl-details { font-size: {{ c.height * 0.1 }}mm; height: {{ c.height * 0.13 }}mm; overflow: hidden; white-space: nowrap; }
	.rbl-bar { height: {{ c.height * 0.36 }}mm; margin: {{ c.height * 0.01 }}mm 0; }
	.rbl-code { font-family: "Courier New", monospace; font-size: {{ c.height * 0.095 }}mm; height: {{ c.height * 0.12 }}mm; text-align: center; letter-spacing: 0.3mm; white-space: nowrap; overflow: hidden; }
	.rbl-foot { font-size: {{ c.height * 0.09 }}mm; height: {{ c.height * 0.12 }}mm; overflow: hidden; white-space: nowrap; }
	.rbl-price { float: right; font-weight: 700; font-size: {{ c.height * 0.11 }}mm; }
</style>
{%- for chunk in c.labels | batch(c.per_row) %}
<table class="rbl-row"><tr>
	{%- for row in chunk %}
	{%- if not loop.first %}<td class="rbl-gap"></td>{% endif %}
	<td><div class="rbl">
		<div class="rbl-name">{{ row.item_name }}</div>
		<div class="rbl-details">{{ row.details or row.item_code }}</div>
		<div class="rbl-bar">{{ barcode_svg(row.barcode) }}</div>
		<div class="rbl-code">{{ row.barcode }}</div>
		<div class="rbl-foot">
			{%- if c.show_price and row.rate %}<span class="rbl-price">{{ frappe.utils.fmt_money(row.rate, currency=c.currency) }}</span>{% endif -%}
			{{ c.footer }}
		</div>
	</div></td>
	{%- endfor %}
	{%- for i in range(c.per_row - chunk | length) %}<td class="rbl-gap"></td><td><div class="rbl"></div></td>{% endfor %}
</tr></table>
{%- endfor %}
